export class MultiPathVerification {
  constructor() {
    this.paths = [];
  }

  addPath(pathFunction) {
    this.paths.push(pathFunction);
  }

  verify(input) {
    const results = this.paths.map((path) => path(input));
    const consistentResults = results.filter((result, index, self) => self.indexOf(result) === index);
    const confidence = consistentResults.length / results.length;
    return { result: consistentResults[0], confidence };
  }
}